-- Origen externo: Certificado de Nivel Avanzado (B2) o superior de Inglés (EOI)
INSERT INTO modulos (id, nombre, id_oficial, id_ciclo) SELECT COALESCE(MAX(id), 0) + 1, 'Certificado de Nivel Avanzado (B2) o superior de Inglés (EOI)', 'certificado_idioma', (SELECT id FROM ciclos WHERE nombre = 'Acreditaciones externas') FROM modulos WHERE NOT EXISTS (  SELECT 1 FROM modulos m   JOIN ciclos c ON c.id = m.id_ciclo   WHERE c.nombre = 'Acreditaciones externas'     AND m.nombre = 'Certificado de Nivel Avanzado (B2) o superior de Inglés (EOI)');
